struct SurferDataStruct {
    int start_stand, start_turn, start_carve, start_anims, end_anims;
    int trickBook[70];
    int learnedtrickBook[16];
    char rest[288];
};
typedef SurferDataStruct SurferData;

struct CareerDataStruct {
    int beach;
    int goal_param[5];
    int reward_param[5];
    char beach_file[32];
    char name[32];
    int goal[5];
    int goal_param_2[5];
    int reward[5];
    int prev_levels[4];
    int next_levels[2];
    float level_duration;
    char stash_name[15];
    int use_ai_surfer;
    char challenge_name[32];
};
typedef CareerDataStruct CareerData;

class game {
public:
    char pad0[116];
    int game_mode;
    char pad1[64];
    int active_player;
    char pad2[356];
    int levelid;
    char pad3[48];
    int surferIdx[2];
    int get_game_mode() { return game_mode; }
    int get_active_player() { return active_player; }
    int get_level_id() { return levelid; }
    int GetSurferIdx(int hero_num) const { return surferIdx[hero_num]; }
};

extern game *g_game_ptr;
extern SurferData SurferDataArray[];
extern CareerData CareerDataArray[];
extern bool FEDone();

#define TRICKBOOK_SIZE 70
#define NUM_EARNED_TRICKS_PER_SURFER 14
#define NUM_LEARNED_TRICKS_PER_SURFER 2
#define GOAL_LEARN_NEW_TRICK 34
#define GAME_MODE_CAREER 0

class Career {
public:
    int spin, speed, jump, balance;
    int current_beach;
    int my_id;
    int my_board_id;
    char myInitials[4];
    int num_special_challenges_completed;
    bool using_personality_suit;
    int num_earned_tricks;
    bool learned_tricks[NUM_EARNED_TRICKS_PER_SURFER + NUM_LEARNED_TRICKS_PER_SURFER];

    bool IsTrickOpen(int trick_num, bool ignore_current_level);
};

bool Career::IsTrickOpen(int trick_num, bool ignore_current_level)
{
    int i;
    int current_surfer = g_game_ptr->GetSurferIdx(g_game_ptr->get_active_player());

    bool trick_exists = false;
    for(i = 0; i < TRICKBOOK_SIZE; i++)
    {
        if(SurferDataArray[current_surfer].trickBook[i] == trick_num)
            trick_exists = true;
    }
    if(!trick_exists)
        return false;

    trick_exists = false;
    for(i = 0; i < (NUM_EARNED_TRICKS_PER_SURFER + NUM_LEARNED_TRICKS_PER_SURFER); i++)
    {
        if(trick_num == SurferDataArray[current_surfer].learnedtrickBook[i])
        {
            trick_exists = true;
            if(learned_tricks[i])
                return true;
        }
    }
    if(!trick_exists)
        return true;

    if(FEDone())
    {
        int current_level = g_game_ptr->get_level_id();
        if (!ignore_current_level &&
            CareerDataArray[current_level].goal[0] == GOAL_LEARN_NEW_TRICK &&
            g_game_ptr->get_game_mode() == GAME_MODE_CAREER &&
            trick_num == SurferDataArray[current_surfer].learnedtrickBook[CareerDataArray[current_level].goal_param[0]])
            return true;
    }

    return false;
}
